<script setup lang="ts">
import {ref,watch,onMounted,onUnmounted} from 'vue'
import {ImageOff,Music,Film} from 'lucide-vue-next'
import {useLocal} from '../stores/local'
import type {Document} from '../domain/local-contract'
import type {LocalAsset} from './contract'
import {assetBytes} from './assets'
const props=defineProps<{asset:Document<LocalAsset>;full?:boolean}>(),store=useLocal(),root=ref<HTMLElement|null>(null),url=ref(''),error=ref(''),visible=ref(false)
let observer:IntersectionObserver|null=null,epoch=0,disposed=false
function clear(){root.value?.querySelectorAll('audio,video').forEach(element=>{const media=element as HTMLMediaElement;media.pause();media.removeAttribute('src');media.load()});if(url.value)URL.revokeObjectURL(url.value);url.value=''}
async function load(){const vault=store.vault,row=props.asset,ticket=++epoch;clear();error.value='';if(!vault||!visible.value||!props.full&&row.value.mediaKind!=='image')return;try{const bytes=await assetBytes(vault,row.value);let blob=new Blob([Uint8Array.from(bytes)],{type:row.value.mime});if(!props.full&&row.value.mediaKind==='image'){const bitmap=await createImageBitmap(blob,{resizeWidth:Math.min(360,row.value.width||360),resizeQuality:'high'});try{const canvas=document.createElement('canvas');canvas.width=bitmap.width;canvas.height=bitmap.height;canvas.getContext('2d')!.drawImage(bitmap,0,0);blob=await new Promise<Blob>((resolve,reject)=>canvas.toBlob(value=>value?resolve(value):reject(new Error('缩略图无法生成')),'image/webp',.78))}finally{bitmap.close()}}if(disposed||ticket!==epoch||store.vault!==vault||!vault.unlocked)return;url.value=URL.createObjectURL(blob)}catch(e){if(!disposed&&ticket===epoch)error.value=(e as Error).message}}
function locked(){epoch++;clear()}
watch(()=>[props.asset.id,props.full,visible.value],()=>void load())
onMounted(()=>{window.addEventListener('reader-local-locked',locked);observer=new IntersectionObserver(entries=>{visible.value=entries.some(entry=>entry.isIntersecting)},{rootMargin:'120px'});if(root.value)observer.observe(root.value)})
onUnmounted(()=>{disposed=true;epoch++;clear();observer?.disconnect();window.removeEventListener('reader-local-locked',locked)})
</script>
<template><div ref="root" class="final-asset-view" :class="{'full':full}" :style="asset.value.mediaKind==='image'&&asset.value.width&&asset.value.height?{aspectRatio:asset.value.width+'/'+asset.value.height}:undefined"><img v-if="url&&asset.value.mediaKind==='image'" :src="url" :alt="asset.value.name" decoding="async"><audio v-else-if="url&&asset.value.mediaKind==='audio'" :src="url" controls preload="metadata" :aria-label="asset.value.name"/><video v-else-if="url&&asset.value.mediaKind==='video'" :src="url" controls playsinline preload="metadata" :aria-label="asset.value.name"/><div v-else class="final-asset-placeholder"><ImageOff v-if="asset.value.mediaKind==='image'" :size="26"/><Music v-else-if="asset.value.mediaKind==='audio'" :size="26"/><Film v-else :size="26"/><span>{{error||asset.value.name}}</span></div></div></template>
<style scoped>.final-asset-view{width:100%;min-height:100px;max-height:260px;background:var(--wash);border-radius:14px;overflow:hidden;display:grid;place-items:center}.final-asset-view img{width:100%;height:100%;object-fit:cover}.final-asset-view.full{max-height:65vh;min-height:130px}.full img{object-fit:contain;max-height:65vh}.final-asset-view video{max-width:100%;max-height:65vh}.final-asset-view audio{width:100%}.final-asset-placeholder{display:grid;justify-items:center;gap:10px;padding:24px;font-size:13px;text-align:center;color:var(--muted);overflow-wrap:anywhere}</style>
